{
 "cases": [
  {
   "name": "正常请求，模型支持图片输入",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "流式请求，模型支持图片输入",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": true,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "温度参数取值恰好在上限",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 2.1,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "温度参数取值恰好在下限",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.4,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "模型不存在",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "invalid",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 404,
   "expect_code": "model_not_found"
  },
  {
   "name": "Key 不存在",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "invalid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 401,
   "expect_code": "invalid_api_key"
  },
  {
   "name": "模型类型与接口不匹配",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-backup",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_kind_mismatch"
  },
  {
   "name": "max_tokens 大于 4096",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 4097,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "消息里有图片但模型不支持图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "image_not_supported"
  },
  {
   "name": "任意消息内容包含拦截词",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "违禁词示例"
     }
    ],
    "temperature": 0.5,
    "max_tokens": 100,
    "n": 1,
    "stream": false,
    "stop": null
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "content_filter"
  }
 ]
}
